import{i as e,n as t,r as n,t as r}from"./pt-BR-vZKB7cQS2.js";import{a as i,c as a,i as o,l as s,n as c,o as l,r as u,s as d,t as f,u as p}from"./pt-BR-JaumcI072.js";import{n as m,r as h,t as g}from"./pt-BR-DugleVDk.js";import{t as _}from"./pt-BR-sZ9aav-o.js";import{i as v,n as y,r as b,t as x}from"./pt-BR-BJ6c1q7P.js";var S={Fi:()=>`Seleção avançada de modelos`,Fj:e,Fk:()=>`Use quando os metadados estiverem ausentes, forem desconhecidos ou não puderem ser lidos. Modelos não detectados continuam selecionáveis; a geração ainda os verifica e pode informar que não são compatíveis.`,Fl:_,Fm:p,Fn:s,Fp:a,Fq:d,Fr:l,Fs:()=>`Cancel and discard`,Ft:()=>`Get audio so far`,Fv:n,Fw:()=>`Verificando os metadados dos modelos locais…`,Fx:t,Fz:()=>`The prompt needs more context. Shorten the text/reference or increase the context size.`,FA:()=>`Este é o tamanho de contexto solicitado. A alocação é limitada pelo contexto de treinamento do modelo e pode ser reduzida se faltar memória. Um contexto maior usa mais memória e não acelera a geração. É independente do limite de etapas de áudio.`,FB:i,FE:v,FF:()=>`Decodificando o áudio gerado…`,FG:()=>`Excluir todos os áudios`,FN:()=>`The model produced no audio samples. Check the model pair and try a short sentence with a different seed.`,FO:()=>`Finish generation and keep audio`,FP:()=>`Finish generation and keep audio ends further steps. Cancel and discard drops audio not yet captured. Audio already added to history remains.`,FR:()=>`Finishing the current step, then converting the audio…`,FS:()=>`Generate audio`,FT:b,FU:()=>`Audio generation failed. Report the code below and the [llama-cpp-browser] console diagnostics. GPU failures may require selecting CPU and trying again.`,FW:()=>`Generation stopped. No partial audio was published.`,FX:({count:e,mebibytes:t})=>`${e} resultado(s) · ${t} MiB de áudio (mais a memória de reprodução)`,FY:()=>`Enter a short sentence for the first test.`,FZ:o,F_:()=>`Um espaço independente para gerar fala no navegador. Com o aplicativo, o ambiente de execução e o modelo disponíveis localmente, a geração funciona offline. O texto e a voz de referência não são enviados a um servidor. A conexão só é necessária para obter arquivos ausentes ou atualizações.`,Ga:r,Gd:u,Ge:()=>`O idioma inicial segue o idioma do aplicativo quando há suporte. Selecione o idioma explicitamente. O padrão do modelo usa inglês no Qwen, não detecção automática. O Pocket usa o idioma em que foi treinado, independentemente desta configuração.`,Gg:()=>`Models and runtime`,Gh:c,Gk:y,Gl:()=>`Os candidatos são identificados pelos metadados do modelo local e do componente de áudio selecionado. Isso não garante compatibilidade nem qualidade. A verificação não carrega modelos para inferência nem faz downloads.`,Gm:()=>`Import a matching backbone GGUF and audio mmproj together as one model folder, or download the pair with the repository browser below. Keep only one backbone (or its shards) and one matching mmproj in the folder. Chat model suggestions are not shown here.`,Gn:()=>`Supported native pipelines: Qwen3-TTS Base and Pocket TTS. CustomVoice and VoiceDesign are not supported by this screen. Compatibility is checked after loading, not guessed from filenames. Runtime profile settings are shared with browser chat inference.`,Go:()=>`Detailed native diagnostics in the console`,Gp:()=>`Nenhum candidato à geração de áudio foi detectado.`,Gr:()=>`Não detectado como modelo de áudio`,Gt:()=>`Os áudios concluídos e suas configurações ficam na memória enquanto esta página estiver aberta, inclusive durante a próxima geração. Exclua resultados individuais ou todos para liberá-los. Nada é salvo automaticamente: salve os WAV necessários antes de sair ou recarregar. A reprodução nunca começa sozinha.`,Gv:()=>`Preparing selected reference audio…`,Gw:()=>`Adds audio so far to history without ending generation. Qwen waits for a completed waveform block; short requests may finish before a preview is available. No automatic playback.`,Gx:()=>`Waiting for a safe audio boundary. Generation will continue.`,Gz:()=>`Esta opção controla apenas o modelo auxiliar de áudio; o principal segue o perfil compartilhado. Seguir o perfil permite usar WebGPU quando disponível, embora algumas operações possam usar a CPU. Forçar a CPU pode ser mais lento, mas permite comparações.`,GN:()=>`Pocket requires a reference voice. Choose an audio file and try again.`,GS:()=>`Reinicializar o ambiente`,GT:()=>`Após um erro, reinicialize sem recarregar a página. Modelos salvos, texto e histórico de áudio são mantidos. Outras tarefas ativas não são interrompidas.`,GU:()=>`Reinicializando o ambiente…`,GX:x,GY:()=>`Open Models and runtime to select an available runtime and import a matching model pair.`,GZ:()=>`Token sampling controls apply to Qwen’s backbone. Top K, top P and seed also pass to the native audio helper. Pocket ignores token sampling and uses its native defaults. Temperature 0 does not guarantee deterministic audio. Step counts are not a predicted completion percentage or a fixed duration.`,G_:f,Hb:()=>`Mostrar todos os modelos salvos do llama.cpp browser`,Hc:()=>`Escolher entre todos os modelos`,Hd:()=>`O limite de etapas é um teto de segurança, não uma duração desejada. A geração para antes quando o modelo termina. Aumentá-lo permite falas mais longas, mas pode aumentar a espera se o modelo não parar.`,He:({completed:e,maximum:t})=>`${e} / ${t} steps (limit)`,Hh:()=>`Stopping and releasing the model…`,Hj:()=>`This model pair does not expose a supported audio-generation pipeline. Choose matching Qwen3-TTS Base or Pocket files, not a chat model or vision projector.`,Hk:()=>`Waiting for the inference lane…`,Ql:h,Qm:m,Qt:g};export{S as default};
